import { Component, createMemo, createSignal, For, onMount, Show } from "solid-js";

import { Layout } from "#core/ui/utilities/utilities-layout.js";
import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { Dropdown, DropdownItem } from "#core/ui-next/components/dropdown.jsx";
import { Hotkeys } from "#core/ui-next/components/hotkeys.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { NavHelp } from "#core/ui-next/components/nav-help.jsx";
import { Popup } from "#core/ui-next/components/popup.jsx";
import { useScreenFlowContext } from "#core/ui-next/components/screen-flow.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { SearchBar } from "#core/ui-next/components/search-bar.jsx";
import { HSlot, SpatialSlot } from "#core/ui-next/components/slot.jsx";
import { Tab } from "#core/ui-next/components/tab.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";
import { useAgeSelectModelContext } from "#core/ui-next/screens/create-game/age-select-model.js";
import { CivCard } from "#core/ui-next/screens/create-game/civ-card.jsx";
import {
	AgeFilterItem,
	attrFilter,
	CivInfo,
	createAgeFilterModel,
	useCivSelectModelContext,
} from "#core/ui-next/screens/create-game/civ-select-model.js";
import { CreateGameHRule } from "#core/ui-next/screens/create-game/create-game-components.jsx";
import {
	CreateGameStage,
	CreateGameStageHeader,
	CreateGameStageMode,
} from "#core/ui-next/screens/create-game/create-game-stage.jsx";
import { LeaderSelectButtonBase } from "#core/ui-next/screens/create-game/leader-select-button.jsx";
import { useLeaderSelectModelContext } from "#core/ui-next/screens/create-game/leader-select-model.js";
import { useRecommendedChoiceModelContext } from "#core/ui-next/screens/create-game/recommended-choice-model.js";
import { CivUnlocksModel } from "#core/ui-next/screens/unlocks/civ-unlocks-model.js";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";
import { ViewExperience } from "#core/ui-next/services/view-experience.js";
import { useIsSmallScreen } from "#core/ui-next/utilities/layout-utilities.js";

import style from "./civ-select-screen.scss?url";

const CivSelectScreenComponent: Component = () => {
	//const leaderModel = LeaderSelectModel.get();
	const model = useCivSelectModelContext();
	const ageModel = useAgeSelectModelContext();
	const leaderModel = useLeaderSelectModelContext();
	const recModel = useRecommendedChoiceModelContext();
	const screenFlow = useScreenFlowContext();
	const ageFilter = createAgeFilterModel();

	const [filtersFocused, setFiltersFocused] = createSignal(false);

	// TODO these should not be filtered by a string name
	const attributeFilters = ["LOC_LEGACIES_FILTER_ALL_ATTRIBUTES"];
	Database.query(
		"config",
		"SELECT * FROM Tags WHERE TagCategoryType = 'TAG_CATEGORY_TRAIT' AND TagType IN (SELECT DISTINCT TagType FROM CivilizationTags)",
	)?.forEach((tag) => {
		if (tag.Name) attributeFilters.push(tag.Name as string);
	});

	const isAgeTransition = createMemo(() => UI.isInGame());

	const [textFilter, setTextFilter] = createSignal<string>("");

	const enableTextFilter = createMemo(() => ViewExperience() == UIViewExperience.Desktop && !IsControllerActive());
	const isSmallScreen = useIsSmallScreen();
	const showSearch = createMemo(() => !isSmallScreen() && enableTextFilter());
	const searchResults = createMemo(() => (textFilter() ? model.fulltextSearch(textFilter()) : new Set<string>()));

	function shouldShowCiv(civ: CivInfo) {
		const matchAge = civ.civID != "RANDOM" && ageFilter.isMatch(civ.apexAge);
		const isPreviousCiv = isAgeTransition() ? civ.civID == model.previousCiv()?.civID : false;

		const matchAttribute =
			civ.civID != "RANDOM" &&
			(attrFilter.getFilter() == "LOC_LEGACIES_FILTER_ALL_ATTRIBUTES" ||
				!attrFilter.getFilter() ||
				civ.traits.some((t) => t == attrFilter.getFilter()));

		const matchText = !enableTextFilter() || !textFilter() || searchResults().has(civ.civID);

		return matchAge && matchAttribute && matchText && !isPreviousCiv;
	}

	function sortCiv(a: CivInfo, b: CivInfo) {
		const invalidSort = (a.isLocked ? 1 : 0) - (b.isLocked ? 1 : 0);

		if (invalidSort == 0) {
			const ageSort = a.ageSortIndex - b.ageSortIndex;

			return ageSort == 0 ? Locale.compare(a.name, b.name) : ageSort;
		}

		return invalidSort;
	}

	function sortCivWithBias(a: CivInfo, b: CivInfo) {
		const civA = recModel.forLeader().get(a.civID);
		const civB = recModel.forLeader().get(b.civID);

		if (!civA || !civB) return sortCiv(a, b);

		const biasSort = civB.bias - civA.bias;
		return biasSort == 0 ? sortCiv(a, b) : biasSort;
	}

	function isRecommended(civType: string) {
		if (!isAgeTransition()) return true;
		return (
			[...recModel.historicalCivs(), ...recModel.recommendedCivs()].filter(
				(c) => GameInfo.Civilizations.lookup(c.civID)?.CivilizationType == civType,
			).length > 0
		);
	}

	const filteredHistoricalCivs = createMemo(() => {
		let civs = recModel.historicalCivs().filter(shouldShowCiv).sort(sortCivWithBias);

		if (isAgeTransition()) {
			const previousCivType = model.previousCiv()?.civID;
			const previousCivInfo = model.civs.filter(
				(c) => GameInfo.Civilizations.lookup(c.civID)?.CivilizationType == previousCivType,
			);

			if (previousCivInfo && previousCivInfo[0]) {
				civs = [previousCivInfo[0], ...civs];
			}
		}

		return civs;
	});
	const filteredRecommendedCivs = createMemo(() =>
		recModel.recommendedCivs().filter(shouldShowCiv).sort(sortCivWithBias),
	);
	const filteredUnrecommendedCivs = createMemo(() =>
		recModel.unrecommendedCivs().filter(shouldShowCiv).sort(sortCiv),
	);

	const groupedCivs = createMemo(() => {
		const ages = {
			AGE_ANTIQUITY: [] as CivInfo[],
			AGE_EXPLORATION: [] as CivInfo[],
			AGE_MODERN: [] as CivInfo[],
		};

		filteredUnrecommendedCivs().forEach((civ) => {
			if (ages[civ.apexAge as keyof typeof ages]) {
				ages[civ.apexAge as keyof typeof ages].push(civ);
			}
		});

		return ages;
	});

	const antiquityCivs = createMemo(() => groupedCivs().AGE_ANTIQUITY);
	const explorationCivs = createMemo(() => groupedCivs().AGE_EXPLORATION);
	const modernCivs = createMemo(() => groupedCivs().AGE_MODERN);

	const numCivs = createMemo(() => {
		return Locale.toNumber(filteredRecommendedCivs().length + filteredUnrecommendedCivs().length);
	});

	function selectCiv(civ: CivInfo) {
		if (!civ.isLocked) {
			model.setSelectedCiv(civ);
		}

		model.setViewCiv(civ);

		// Do some audio here because it's transitioning to another screen
		useAudio("AgeTransition/SelectCiv")("activate");
	}

	function civNameShort(civInfo: CivInfo) {
		// Example: "CIVILIZATION_PIRATE_REPUBLIC" -> "pirate-republic"
		let civName = civInfo?.civID.replaceAll("_", "-").toLowerCase();
		civName = civName.replace("civilization-", "");
		return civName;
	}

	// eslint-disable-next-line solid/reactivity
	const inGameUnlocksModel = isAgeTransition() ? CivUnlocksModel.get() : undefined;

	function getCivInfo(civInfo: CivInfo) {
		return inGameUnlocksModel?.civInfo.find((c) => c.civID == civInfo.civID) ?? civInfo;
	}

	function toggleFiltersFocused() {
		setFiltersFocused((focused) => !focused);
	}

	function updateAgeFilter(item: AgeFilterItem) {
		ageFilter.setSelected(item);
		setFiltersFocused(false);
	}

	function updateAttrFilter(item: string) {
		attrFilter.setFilter(item);
		setFiltersFocused(false);
	}
	const audio = useAudio("CivSelectScreen");

	onMount(() => {
		audio("popup-open");
	});

	return (
		<CreateGameStage
			header={
				<CreateGameStageHeader
					showSteps={!(ViewExperience() == UIViewExperience.Handheld) && !UI.isInGame()}
					title="LOC_UI_CREATE_GAME_CIVILIZATION_SELECT"
					hideButtonText={isAgeTransition() ? "LOC_UI_AGE_TRANSITION_VIEW_MAP" : undefined}
					onBack={() => {
						screenFlow.activatePrev();
						//reset filters
						ageFilter.reset();
						attrFilter.reset();
					}}
				/>
			}
			mode={isAgeTransition() ? CreateGameStageMode.StageOnly : CreateGameStageMode.Full}
		>
			<Hotkeys
				hotkeys={[
					{
						hotkeyAction: "accept",
						navTrayText: "LOC_GENERIC_SELECT",
					},
					{
						hotkeyAction: "cancel",
						navTrayText: "LOC_GENERIC_BACK",
						onActivate: () => {
							screenFlow.activatePrev();
							useAudio("CreateGameBackButton")("activate");

							//reset filters
							ageFilter.reset();
							attrFilter.reset();
						},
					},
					{
						hotkeyAction: "shell-action-2",
						navTrayText: "LOC_UI_FILTER_SORT_FILTERS",
						onActivate: () => toggleFiltersFocused(),
					},
				]}
			/>

			<AudioContextProvider segment="CivSelectScreen">
				<div class="flex flex-col size-full civ-age-select-body flex-auto">
					<div class="flex flex-col ml-10 mr-8">
						<div class="flex flex-row mt-4 mb-2 items-center">
							<Show when={showSearch()}>
								<SearchBar
									value={textFilter}
									setValue={setTextFilter}
									class="w-84"
								/>
							</Show>
							<div class="flex-auto" />
							<span class="mr-3 text-accent-2 uppercase">
								<L10n.Compose
									text="LOC_UI_CREATE_GAME_CIVILIZATIONS_NUMBER"
									args={[numCivs()]}
								/>
							</span>
							<HSlot
								disableFocus={!filtersFocused()}
								autoFocus={filtersFocused()}
							>
								<AudioContextProvider segment="Filters">
									<Dropdown
										defaultValue={ageFilter.selected()}
										selectedItemTemplate={(item) => (
											<div class="mx-2 w-full font-fit-shrink">
												<L10n.Compose
													text="LOC_UI_CREATE_GAME_FILTER_ITEM"
													args={[item.name]}
												/>
											</div>
										)}
										onItemSelected={(item) => updateAgeFilter(item)}
										class="mr-2 min-w-76"
									>
										<For each={ageFilter.options}>
											{(item) => <DropdownItem value={item}>{item.name}</DropdownItem>}
										</For>
									</Dropdown>
									<Dropdown
										defaultValue={attrFilter.getFilter()}
										selectedItemTemplate={(item) => (
											<div class="mx-2 w-full font-fit-shrink">
												<L10n.Compose
													text="LOC_UI_CREATE_GAME_FILTER_ITEM"
													args={[Locale.toUpper(Locale.compose(item))]}
												/>
											</div>
										)}
										onItemSelected={(item) => updateAttrFilter(item)}
										class="min-w-76"
									>
										<For each={attributeFilters}>
											{(item) => (
												<DropdownItem value={item}>
													{Locale.toUpper(Locale.compose(item))}
												</DropdownItem>
											)}
										</For>
									</Dropdown>
								</AudioContextProvider>
							</HSlot>
						</div>
						<CreateGameHRule class="w-full my-2 " />
					</div>
					<div class="flex flex-row flex-auto">
						{/* //MARK: LEFT CONTENT */}
						<div class="flex flex-col items-center h-full w-52">
							<Tooltip.Text text={Locale.compose("LOC_UI_CREATE_GAME_RANDOM")}>
								<AudioContextProvider segment="RandomCivButton">
									<LeaderSelectButtonBase
										isLocked={false}
										isSelected={false}
										disableFocus={true}
										hotkeyAction={"shell-action-1"}
										class="civ-select-leader-button-base self-center"
										onActivate={() => {
											selectCiv(model.randomCiv);
											screenFlow.activate(
												isAgeTransition()
													? "memento-select"
													: screenFlow.wasHubVisited()
														? "create-game-hub"
														: "game-setup",
											);
										}}
									>
										<Icon
											name="LEADER_RANDOM"
											class="civ-select-leader-button-icon"
										/>
										<NavHelp class="absolute bottom-0 right-0" />
									</LeaderSelectButtonBase>
								</AudioContextProvider>
							</Tooltip.Text>
							<L10n.Stylize
								text="LOC_UI_CREATE_GAME_STARTING_AGE"
								class="font-title uppercase civ-select-age-text"
							/>
							<L10n.Stylize
								text={ageModel.getAgeName(ageModel.selectedAge.type) || ""}
								class="font-title uppercase font-black mb-2 civ-select-age-type-text font-fit-shrink"
							/>
							<Popup.Trigger name="age-select">
								<AudioContextProvider segment="AgeSelectPopup">
									<Activatable
										class="civ-select-age-banner relative"
										disabled={isAgeTransition()}
										disableFocus={true}
										hotkeyAction={"shell-action-3"}
									>
										<div class="absolute inset-0 flex flex-col items-center justify-end group">
											<div class="absolute inset-0 img-unit-panelbox pointer-events-none" />
											<div
												class="absolute inset-0"
												style={{
													"background-image": `url(${UI.getIconBLP(ageModel.selectedAge.type, "BACKGROUND_VERT")})`,
													"background-position": "center center",
													"background-size": "cover",
												}}
											/>
											<div class="create-game-hub-bottom-gradient absolute left-0 bottom-0" />
											<div class="absolute inset-0 w-full h-full border-2 border-secondary-3" />
											<div class="img-rollover-highlight absolute inset-0 opacity-0 group-focus\:opacity-100 group-hover\:opacity-100 group-pressed\:opacity-100 pointer-events-none" />
											<div
												class="flex items-center justify-center size-36 relative mb-4"
												style={{
													width: Layout.pixels(132),
													height: Layout.pixels(132),
													"background-image": "url(blp:hud_sub_circle_dis_128x128)",
													"background-repeat": "no-repeat",
													"background-size": "cover",
												}}
											>
												<Icon
													name={ageModel.selectedAge.icon}
													class="size-24 -bottom-px relative"
												/>
											</div>
											<NavHelp class="absolute bottom-2 right-2" />
										</div>
									</Activatable>
								</AudioContextProvider>
							</Popup.Trigger>
						</div>

						{/* //MARK: RIGHT CONTENT */}
						<ScrollArea class="flex-auto">
							<SpatialSlot
								name="civ-select-grid"
								disableFocus={filtersFocused()}
								autoFocus={!filtersFocused()}
								class="civ-select-right-content"
							>
								<Show
									when={
										leaderModel.selectedLeader().leaderID != "RANDOM" &&
										filteredHistoricalCivs().length > 0
									}
								>
									<div class="flex flex-row ml-6 mr-1\.25 mt-1 mb-2 uppercase accent-2 font-bold">
										<L10n.Compose
											text="LOC_UI_CREATE_GAME_HYSTORICAL_CIVILIZATIONS_FOR"
											args={[leaderModel.selectedLeader().rawName]}
										/>
									</div>
									<div class="flex flex-row flex-wrap">
										<For each={filteredHistoricalCivs()}>
											{(civ) => (
												<Tab.Trigger name="civ-details">
													<AudioContextProvider
														segment="CivSelectCard"
														vars={{ civType: civNameShort(civ) }}
													>
														<CivCard
															{...getCivInfo(civ)}
															isSelected={civ.civID == model.selectedCiv().civID}
															isApexAgeSelected={ageModel.selectedAge.type == civ.apexAge}
															leaderIcon={leaderModel.selectedLeader().icon}
															isRecommended={isRecommended(civ.civID)}
															isCivSelect={true}
															isUnlocks={isAgeTransition() && civ.isLocked}
															onSelect={() => selectCiv(civ)}
														/>
													</AudioContextProvider>
												</Tab.Trigger>
											)}
										</For>
									</div>
									<CreateGameHRule class="my-2" />
								</Show>
								<Show
									when={
										leaderModel.selectedLeader().leaderID != "RANDOM" &&
										filteredRecommendedCivs().length > 0
									}
								>
									<div class="flex flex-row ml-6 mr-1\.25 mt-1 mb-2 uppercase accent-2 font-bold">
										<L10n.Compose
											text="LOC_UI_CREATE_GAME_INFLUENTIAL_CIVILIZATIONS_FOR"
											args={[leaderModel.selectedLeader().rawName]}
										/>
									</div>
									<div class="flex flex-row flex-wrap">
										<For each={filteredRecommendedCivs()}>
											{(civ) => (
												<Tab.Trigger name="civ-details">
													<AudioContextProvider
														segment="CivSelectCard"
														vars={{ civType: civNameShort(civ) }}
													>
														<CivCard
															{...getCivInfo(civ)}
															isSelected={civ.civID == model.selectedCiv().civID}
															isApexAgeSelected={ageModel.selectedAge.type == civ.apexAge}
															leaderIcon={leaderModel.selectedLeader().icon}
															isRecommended={true}
															isCivSelect={true}
															isUnlocks={isAgeTransition() && civ.isLocked}
															onSelect={() => selectCiv(civ)}
														/>
													</AudioContextProvider>
												</Tab.Trigger>
											)}
										</For>
									</div>
									<CreateGameHRule class="my-2" />
								</Show>
								<Show when={antiquityCivs().length > 0}>
									<div class="flex flex-row ml-6 mr-1\.25 mt-1 mb-2 uppercase accent-2 font-bold">
										<L10n.Compose
											text="LOC_UI_CREATE_GAME_ANTIQUITY_AGE_CIVILIZATIONS"
											args={[leaderModel.selectedLeader().rawName]}
										/>
									</div>
									<div class="flex flex-row flex-wrap">
										<For each={antiquityCivs()}>
											{(civ) => (
												<Tab.Trigger name="civ-details">
													<AudioContextProvider
														segment="CivSelectCard"
														vars={{ civType: civNameShort(civ) }}
													>
														<CivCard
															{...getCivInfo(civ)}
															isSelected={civ.civID == model.selectedCiv().civID}
															isApexAgeSelected={ageModel.selectedAge.type == civ.apexAge}
															leaderIcon={leaderModel.selectedLeader().icon}
															isRecommended={false}
															isCivSelect={true}
															isUnlocks={isAgeTransition() && civ.isLocked}
															onSelect={() => selectCiv(civ)}
														/>
													</AudioContextProvider>
												</Tab.Trigger>
											)}
										</For>
									</div>
									<CreateGameHRule class="my-2" />
								</Show>
								<Show when={explorationCivs().length > 0}>
									<div class="flex flex-row ml-6 mr-1\.25 mt-1 mb-2 uppercase accent-2 font-bold">
										<L10n.Compose
											text="LOC_UI_CREATE_GAME_EXPLORATION_AGE_CIVILIZATIONS"
											args={[leaderModel.selectedLeader().rawName]}
										/>
									</div>
									<div class="flex flex-row flex-wrap">
										<For each={explorationCivs()}>
											{(civ) => (
												<Tab.Trigger name="civ-details">
													<AudioContextProvider
														segment="CivSelectCard"
														vars={{ civType: civNameShort(civ) }}
													>
														<CivCard
															{...getCivInfo(civ)}
															isSelected={civ.civID == model.selectedCiv().civID}
															isApexAgeSelected={ageModel.selectedAge.type == civ.apexAge}
															leaderIcon={leaderModel.selectedLeader().icon}
															isRecommended={false}
															isCivSelect={true}
															isUnlocks={isAgeTransition() && civ.isLocked}
															onSelect={() => selectCiv(civ)}
														/>
													</AudioContextProvider>
												</Tab.Trigger>
											)}
										</For>
									</div>
									<CreateGameHRule class="my-2" />
								</Show>
								<Show when={modernCivs().length > 0}>
									<div class="flex flex-row ml-6 mr-1\.25 mt-1 mb-2 uppercase accent-2 font-bold">
										<L10n.Compose
											text="LOC_UI_CREATE_GAME_MODERN_AGE_CIVILIZATIONS"
											args={[leaderModel.selectedLeader().rawName]}
										/>
									</div>
									<div class="flex flex-row flex-wrap">
										<For each={modernCivs()}>
											{(civ) => (
												<Tab.Trigger name="civ-details">
													<AudioContextProvider
														segment="CivSelectCard"
														vars={{ civType: civNameShort(civ) }}
													>
														<CivCard
															{...getCivInfo(civ)}
															isSelected={civ.civID == model.selectedCiv().civID}
															isApexAgeSelected={ageModel.selectedAge.type == civ.apexAge}
															leaderIcon={leaderModel.selectedLeader().icon}
															isRecommended={false}
															isCivSelect={true}
															isUnlocks={isAgeTransition() && civ.isLocked}
															onSelect={() => selectCiv(civ)}
														/>
													</AudioContextProvider>
												</Tab.Trigger>
											)}
										</For>
									</div>
								</Show>
							</SpatialSlot>
						</ScrollArea>
					</div>
				</div>
			</AudioContextProvider>
		</CreateGameStage>
	);
};

export const CivSelectScreen = ComponentRegistry.register({
	name: "CivSelectScreen",
	createInstance: CivSelectScreenComponent,
	styles: [style],
});
